Plan:
Read the main sheet into a location-to-employee map. For each result row, fill B:D with designation, contact, and email if the designation is Branch Manager or Branch Credit Manager, otherwise N/A. Save the workbook with left-aligned plain values.

```python
import shutil
import openpyxl
from openpyxl.styles import Alignment

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

main_ws = vals["main sheet"]
result_ws = wb["result"]

def clean(value):
    if value is None:
        return None
    if isinstance(value, str):
        s = value.strip()
        return s if s else None
    return value

def to_text(value):
    if value is None:
        return ""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()

main_map = {}
for row in main_ws.iter_rows(min_row=2, values_only=True):
    if not row:
        continue
    location = clean(row[0])
    if location is None:
        continue
    name = clean(row[1])
    contact = clean(row[2])
    mail = clean(row[3])
    designation = clean(row[4])
    main_map[location] = (name, contact, mail, designation)

valid_designations = {"Branch Manager", "Branch Credit Manager"}
left_align = Alignment(horizontal="left", vertical="center")

for r in range(2, 13):
    location = clean(result_ws.cell(row=r, column=1).value)
    if location is None:
        continue

    if location in main_map:
        name, contact, mail, designation = main_map[location]
        if designation in valid_designations:
            b_val = designation
            c_val = contact
            d_val = mail
        else:
            b_val = "N/A"
            c_val = "N/A"
            d_val = "N/A"
    else:
        b_val = "N/A"
        c_val = "N/A"
        d_val = "N/A"

    for col, value in ((2, b_val), (3, c_val), (4, d_val)):
        cell = result_ws.cell(row=r, column=col)
        cell.value = value
        cell.alignment = left_align

    print(r, location, b_val, c_val, d_val)

wb.save(OUT)
